const assert = require('assert').strict;
const { buildWeb } = require('../../build/web.cjs');
const env = { CF_PAGES: '1', SKIP_DEPENDENCY_INSTALL: '1' };
const calls = [];
const run = (cmd, args) => { calls.push([cmd, args]); return { status: 0, stdout: '1.22.22\n' }; };
buildWeb({ env: {}, argv: [], run });
assert.deepEqual(calls.splice(0), [['yarn', ['run', 'build:web:base']]]);
buildWeb({ env, argv: [], run, version: 'v22.22.2' });
assert.equal(calls.length, 1);
assert.deepEqual(calls[0][1].slice(0, 5), ['exec', '--yes', '--package=node@16.20.2', '--package=yarn@1.22.22', '--']);
calls.length = 0;
buildWeb({ env, argv: ['--pages-install'], run, version: 'v16.20.2' });
assert.deepEqual(calls, [['yarn',['--version']],['yarn',['install','--frozen-lockfile']],['yarn',['run','build:web:base']]]);
assert.throws(() => buildWeb({ env, argv: ['--pages-install'], run, version: 'v22.22.2' }), /Node 16/);
assert.throws(() => buildWeb({ env, argv: ['--pages-install'], run: () => ({status:0,stdout:'4.9.1'}), version: 'v16.20.2' }), /Yarn 1/);
let count = 0;
assert.throws(() => buildWeb({ env, argv: ['--pages-install'], version: 'v16.20.2', run: () => ({status: ++count === 1 ? 0 : 1, stdout:'1.22.22'}) }), /failed/);
assert.equal(count, 2);
console.log('PASS Pages bootstrap, frozen install, original build route and fail-closed runtime checks');
